-- Every COD entry for the six formulas (silicon also has clathrates, hexagonal and
-- high-pressure forms; carbon has graphite), with its cell edge a in Å.
SELECT 'Si' AS material, 'Si' AS atom_a, 'Si' AS atom_b, 'diamond' AS structure, CAST(file AS VARCHAR) AS file, CAST(a AS VARCHAR) AS a, CAST(sg AS VARCHAR) AS sg, CAST(year AS VARCHAR) AS year, CAST(title AS VARCHAR) AS title, CAST(celltemp AS VARCHAR) AS celltemp FROM data
UNION ALL SELECT 'Ge' AS material, 'Ge' AS atom_a, 'Ge' AS atom_b, 'diamond' AS structure, CAST(file AS VARCHAR) AS file, CAST(a AS VARCHAR) AS a, CAST(sg AS VARCHAR) AS sg, CAST(year AS VARCHAR) AS year, CAST(title AS VARCHAR) AS title, CAST(celltemp AS VARCHAR) AS celltemp FROM data1
UNION ALL SELECT 'diamond (C)' AS material, 'C' AS atom_a, 'C' AS atom_b, 'diamond' AS structure, CAST(file AS VARCHAR) AS file, CAST(a AS VARCHAR) AS a, CAST(sg AS VARCHAR) AS sg, CAST(year AS VARCHAR) AS year, CAST(title AS VARCHAR) AS title, CAST(celltemp AS VARCHAR) AS celltemp FROM data2
UNION ALL SELECT 'GaAs' AS material, 'Ga' AS atom_a, 'As' AS atom_b, 'zincblende' AS structure, CAST(file AS VARCHAR) AS file, CAST(a AS VARCHAR) AS a, CAST(sg AS VARCHAR) AS sg, CAST(year AS VARCHAR) AS year, CAST(title AS VARCHAR) AS title, CAST(celltemp AS VARCHAR) AS celltemp FROM data3
UNION ALL SELECT 'AlAs' AS material, 'Al' AS atom_a, 'As' AS atom_b, 'zincblende' AS structure, CAST(file AS VARCHAR) AS file, CAST(a AS VARCHAR) AS a, CAST(sg AS VARCHAR) AS sg, CAST(year AS VARCHAR) AS year, CAST(title AS VARCHAR) AS title, CAST(celltemp AS VARCHAR) AS celltemp FROM data4
UNION ALL SELECT 'InP' AS material, 'In' AS atom_a, 'P' AS atom_b, 'zincblende' AS structure, CAST(file AS VARCHAR) AS file, CAST(a AS VARCHAR) AS a, CAST(sg AS VARCHAR) AS sg, CAST(year AS VARCHAR) AS year, CAST(title AS VARCHAR) AS title, CAST(celltemp AS VARCHAR) AS celltemp FROM data5